 let ex=[["bench","Press de banca","Pecho","🏋️","Empuja con control y mantén los pies firmes.","Banco y barra"],["squat","Sentadilla","Piernas","🦵","Baja hasta donde mantengas una postura cómoda.","Peso corporal o mochila"],["row","Remo con mancuerna","Espalda","💪","Lleva el codo hacia la cadera.","Mancuerna o mochila"],["rdl","Peso muerto rumano","Piernas","⚡","Cadera atrás, espalda larga y movimiento suave.","Mancuerna o mochila"],["shoulder","Press de hombros","Hombros","⭐","Evita arquear la espalda.","Mancuernas"],["plank","Plancha","Core","🧘","Mantén una línea cómoda.","Sin material"],["lunge","Zancadas","Piernas","🔥","Paso estable, controla la bajada.","Sin material"],["pulldown","Jalón al pecho","Espalda","🏋️","Lleva la barra a la parte alta del pecho.","Banda o polea"]].map(x=>({id:x[0],name:x[1],group:x[2],icon:x[3],notes:x[4],equipment:x[5],updatedAt:Date.now()}));
