let start=startWeek(new Date(),state.settings.weekStart===0?0:1),strip="";for(let i=0;i<7;i++){let d=new Date(start);d.setDate(start.getDate()+i);let iso=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"),wi=(d.getDay()+6)%7,tr=state.sessions[iso]&&Object.values(state.sessions[iso].sets||{}).some(x=>x&&x.done);strip+='<div class="week-day '+(iso===today?"active ":"")+(tr?"trained":"")+'">'+WD[wi]+'<b>'+d.getDate()+'</b></div>'}
