function wireRoutineOrder(){document.querySelectorAll(".routine-item").forEach(el=>{if(!el.querySelector("[data-step]")){let a=document.createElement("span");a.className="row-actions";a.innerHTML='<button type="button" data-step="-1" aria-label="Mover arriba">↑</button><button type="button" data-step="1" aria-label="Mover abajo">↓</button>';el.appendChild(a)}el.querySelectorAll("[data-step]").forEach(b=>b.onclick=e=>{e.stopPropagation();let id=el.dataset.ri,i=Number(el.dataset.idx),to=Math.max(0,Math.min(state.routines.find(x=>x.id===id).items.length-1,i+Number(b.dataset.step)));if(to!==i)change(s=>{let r=s.routines.find(x=>x.id===id),m=r.items.splice(i,1)[0];r.items.splice(to,0,m);r.updatedAt=Date.now()})});el.ondragstart=()=>{dragged=el.dataset.ri+"|"+el.dataset.idx;el.classList.add("dragging")};el.ondragend=()=>el.classList.remove("dragging");el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(!dragged)return;let p=dragged.split("|"),sr=p[0],si=Number(p[1]),dr=el.dataset.ri,di=Number(el.dataset.idx);if(sr===dr)change(s=>{let r=s.routines.find(x=>x.id===sr),m=r.items.splice(si,1)[0];r.items.splice(di,0,m);r.updatedAt=Date.now()});dragged=null}})}
