dlg.addEventListener("click",e=>{if(e.target===dlg)dlg.close()});
function editExercise(id){
let old=id?state.exercises.find(x=>x.id===id):null,e=old||{name:"",group:"",icon:"💪",notes:"",equipment:""};
openDialog('<div class="dialog-head"><h2>'+(old?"Editar ejercicio":"Crear ejercicio")+'</h2><button class="icon-btn" data-close>×</button></div><p class="small-copy">Añade cualquier movimiento que puedas hacer con el espacio y el material que tienes.</p><form id="exForm"><div class="field"><label>Nombre del ejercicio</label><input name="name" required maxlength="70" value="'+esc(e.name)+'" placeholder="Ej. Flexiones contra la pared"></div><div class="field"><label>Grupo o categoría</label><input name="group" maxlength="50" value="'+esc(e.group)+'" list="groups" placeholder="Ej. Pecho, piernas, movilidad"><datalist id="groups">'+[...new Set(state.exercises.map(x=>x.group))].map(x=>'<option value="'+esc(x)+'"></option>').join("")+'</datalist></div><div class="field"><label>Material (opcional)</label><input name="equipment" maxlength="70" value="'+esc(e.equipment||"")+'" placeholder="Sin material, silla, mochila..."></div><div class="field"><label>Icono (emoji)</label><input name="icon" maxlength="8" value="'+esc(e.icon)+'"></div><div class="field"><label>Notas o indicaciones (opcional)</label><textarea name="notes" maxlength="300" placeholder="Una variante, postura o recordatorio">'+esc(e.notes)+'</textarea></div><div class="actions"><button class="button">Guardar ejercicio</button></div></form>');
closeDialog();document.getElementById("exForm").onsubmit=eve=>{eve.preventDefault();let f=new FormData(eve.target),v={name:String(f.get("name")).trim(),group:String(f.get("group")).trim()||"Otros",equipment:String(f.get("equipment")).trim(),icon:String(f.get("icon")).trim()||"💪",notes:String(f.get("notes")).trim(),updatedAt:Date.now()};change(s=>{if(old)Object.assign(s.exercises.find(x=>x.id===id),v);else s.exercises.push(Object.assign({id:uid()},v))});dlg.close();toast(old?"Ejercicio actualizado.":"Ejercicio añadido.")}
}
function editRoutine(id){
let old=id?state.routines.find(x=>x.id===id):null,r=old||{name:"",items:[]},selected=new Set(r.items.map(x=>x.exerciseId));
let opts=state.exercises.map(x=>'<label class="field inline"><label>'+esc(x.icon)+' '+esc(x.name)+' <span class="muted">· '+esc(x.group)+(x.equipment?" · "+esc(x.equipment):"")+'</span></label><input type="checkbox" name="ex" value="'+esc(x.id)+'" '+(selected.has(x.id)?"checked":"")+'></label>').join("");
openDialog('<div class="dialog-head"><h2>'+(old?"Editar rutina":"Crear rutina")+'</h2><button class="icon-btn" data-close>×</button></div><form id="routineForm"><div class="field"><label>Nombre</label><input name="name" required maxlength="70" value="'+esc(r.name)+'" placeholder="Ej. Tren superior"></div><div class="field"><label>Ejercicios</label>'+(opts||'<p class="small-copy">Primero crea movimientos que puedas hacer con el espacio y material que tienes en casa.</p><button type="button" class="button secondary small" id="go-exercises">Crear ejercicio</button>')+'</div><div class="field"><label>Series por ejercicio</label><input name="sets" type="number" min="1" max="20" value="'+(r.items[0]?.sets||3)+'"></div><div class="field"><label>Repeticiones</label><input name="reps" value="'+esc(r.items[0]?.reps||"8–12")+'"></div><div class="field"><label>Peso inicial ('+esc(state.settings.unit)+')</label><input name="weight" type="number" min="0" step=".5" value="'+(r.items[0]?.weight||0)+'"></div><div class="field"><label>Descanso en segundos</label><input name="rest" type="number" min="0" value="'+(r.items[0]?.rest||state.settings.defaultRest)+'"></div><div class="actions"><button class="button">Guardar rutina</button></div></form>');
closeDialog();document.getElementById("go-exercises")?.addEventListener("click",()=>{dlg.close();nav("library")});document.getElementById("routineForm").onsubmit=eve=>{eve.preventDefault();let f=new FormData(eve.target),ids=Array.from(document.querySelectorAll('[name="ex"]:checked')).map(x=>x.value),n=Math.max(1,Number(f.get("sets"))||3),reps=String(f.get("reps")||"8–12"),weight=Number(f.get("weight"))||0,rest=Math.max(0,Number(f.get("rest"))||60);let items=ids.map(exId=>{let prior=old&&old.items.find(x=>x.exerciseId===exId);return {id:prior?prior.id:uid(),exerciseId:exId,sets:n,reps,weight,rest,updatedAt:Date.now()}});change(s=>{if(old){let dest=s.routines.find(x=>x.id===id);dest.name=String(f.get("name")).trim();dest.items=items;dest.updatedAt=Date.now()}else s.routines.push({id:uid(),name:String(f.get("name")).trim(),items,updatedAt:Date.now()})});dlg.close();toast("Rutina guardada.")}
}
function showTimer(){
openDialog('<div class="dialog-head"><h2>⏱ Descanso</h2><button class="icon-btn" data-close>×</button></div><div class="timer-face" id="timerFace">'+clockText(timerLeft||Number(state.settings.defaultRest||60))+'</div><div class="timer-row">'+[30,60,90].map(n=>'<button class="button secondary small" data-sec="'+n+'">'+n+' s</button>').join("")+'<button class="button secondary small" id="customSec">Personalizado</button></div><div class="actions" style="justify-content:center"><button class="button" id="timerToggle">'+(timer?"Pausar":"Empezar")+'</button><button class="button secondary" id="timerReset">Reiniciar</button></div>');
closeDialog();document.querySelectorAll("[data-sec]").forEach(b=>b.onclick=()=>setTimer(Number(b.dataset.sec)));document.getElementById("customSec").onclick=()=>{let x=Number(prompt("¿Cuántos segundos?","120"));if(x>0)setTimer(x)};
document.getElementById("timerToggle").onclick=()=>{if(timer){clearInterval(timer);timer=null;document.getElementById("timerToggle").textContent="Empezar"}else startTimer(timerLeft||Number(state.settings.defaultRest||60))};
document.getElementById("timerReset").onclick=()=>{clearInterval(timer);timer=null;timerLeft=Number(state.settings.defaultRest||60);document.getElementById("timerFace").textContent=clockText(timerLeft);document.getElementById("timerToggle").textContent="Empezar"}
}
function clockText(n){return String(Math.floor(n/60)).padStart(2,"0")+":"+String(n%60).padStart(2,"0")}
function setTimer(n){clearInterval(timer);timer=null;timerLeft=n;let f=document.getElementById("timerFace");if(f)f.textContent=clockText(n)}
function startTimer(n){timerLeft=n;timerEnd=Date.now()+n*1000;clearInterval(timer);timer=setInterval(()=>{timerLeft=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));let f=document.getElementById("timerFace");if(f)f.textContent=clockText(timerLeft);if(!timerLeft){clearInterval(timer);timer=null;if(navigator.vibrate)navigator.vibrate([250,100,250]);toast("¡Descanso terminado! A por la siguiente 💪");let b=document.getElementById("timerToggle");if(b)b.textContent="Empezar"}},250);let b=document.getElementById("timerToggle");if(b)b.textContent="Pausar"}
function party(){let c=document.getElementById("confetti"),colors=["#ff786b","#51c9a5","#f2c351","#40b9c8","#8996ff"];c.innerHTML=Array.from({length:40},(_,i)=>'<i style="left:'+Math.random()*100+'%;background:'+colors[i%5]+';animation-delay:'+Math.random()*.35+'s"></i>').join("");setTimeout(()=>c.innerHTML="",2200)}
function exportData(){try{state.settings.lastBackup=Date.now();saveSoon();let payload={app:"Ritmo",exportedAt:new Date().toISOString(),schemaVersion:SV,data:state,backups:Store.backups},blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="ritmo-copia-"+today+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200);toast("Copia JSON descargada.")}catch(e){toast("No se pudo crear el archivo de copia.")}}
document.getElementById("importFile").onchange=async e=>{let file=e.target.files&&e.target.files[0];if(!file)return;let oldState=cp(state),oldBackups=cp(Store.backups);try{let obj=JSON.parse(await file.text()),incoming=obj.data||obj;if(!valid(incoming))throw Error("El archivo no tiene una estructura válida de Ritmo.");let next=migrate(incoming),newBackups=Array.isArray(obj.backups)?obj.backups.filter(b=>b&&valid(b.data)).slice(0,5):[];if(!confirm("El archivo es válido. Contiene "+next.exercises.length+" ejercicios y "+next.routines.length+" rutinas. ¿Sustituir los datos actuales?"))return;state=next;state.writer=WRITER;Store.backups=newBackups;let res=await Store.save(state);if(!res.ok){state=oldState;Store.backups=oldBackups;Store.current=cp(oldState);applySettings();render();throw Error("No se pudo guardar la importación; conservé tus datos actuales.")}state=cp(Store.current);setStatus(res.idbOK,res.idbOK?"Guardado ✓":"Guardado en copia local");applySettings();render();if(!res.idbOK)toast("Importado en la copia local. IndexedDB no respondió; exporta otra copia.",{label:"Exportar",run:exportData});else toast("Datos importados correctamente.")}catch(err){toast("No se importó: "+(err.message||"archivo inválido"))}finally{e.target.value=""}}

function mergeList(a,b,aw,bw){let m=new Map();[...(a||[]),...(b||[])].forEach(x=>{if(!x)return;let key=x.id||x.date;if(!key)return;let prev=m.get(key);if(!prev||(x.updatedAt||0)>(prev.updatedAt||0)||((x.updatedAt||0)===(prev.updatedAt||0)&&String(bw)>String(aw)))m.set(key,cp(x))});return Array.from(m.values())}
function mergeData(a,b){
if(!valid(a))return migrate(b);if(!valid(b))return migrate(a);
let l=migrate(a),r=migrate(b),preferRight=(r.updatedAt||0)>(l.updatedAt||0)||((r.updatedAt||0)===(l.updatedAt||0)&&String(r.writer)>String(l.writer));
l.exercises=mergeList(l.exercises,r.exercises,l.writer,r.writer);l.routines=mergeList(l.routines,r.routines,l.writer,r.writer);l.templates=mergeList(l.templates,r.templates,l.writer,r.writer);l.bodyWeights=mergeList(l.bodyWeights,r.bodyWeights,l.writer,r.writer);
Object.keys(r.sessions).forEach(day=>{let x=l.sessions[day],y=r.sessions[day];if(!x){l.sessions[day]=cp(y);return}if((y.updatedAt||0)>(x.updatedAt||0))l.sessions[day]=cp(y);else{Object.keys(y.sets||{}).forEach(k=>{let old=x.sets[k],incoming=y.sets[k];if(!old||(incoming.updatedAt||y.updatedAt||0)>(old.updatedAt||x.updatedAt||0)||((incoming.updatedAt||y.updatedAt||0)===(old.updatedAt||x.updatedAt||0)&&preferRight))x.sets[k]=cp(incoming)});if((y.updatedAt||0)>(x.updatedAt||0)){x.note=y.note;x.bodyWeight=y.bodyWeight;x.updatedAt=y.updatedAt}}});
if((r.plan.updatedAt||0)>(l.plan.updatedAt||0)||((r.plan.updatedAt||0)===(l.plan.updatedAt||0)&&preferRight))l.plan=cp(r.plan);
if(preferRight){l.settings=Object.assign({},l.settings,r.settings)}
l.updatedAt=Math.max(l.updatedAt||0,r.updatedAt||0);l.writer=preferRight?r.writer:l.writer;return l
}
function broadcast(){try{if(bus)bus.postMessage({type:"state",data:state})}catch(e){}}
function remote(d){if(!valid(d)||d.writer===WRITER)return;let merged=mergeData(state,d);if(JSON.stringify(merged)!==JSON.stringify(state)){state=merged;Store.save(state).then(()=>{state=cp(Store.current);applySettings();render();setStatus(true,"Sincronizado ✓")}).catch(()=>setStatus(false,"Error al sincronizar"))}}
function setupSync(){try{if("BroadcastChannel" in window){bus=new BroadcastChannel("ritmo-sync");bus.onmessage=e=>{if(e.data&&e.data.type==="state")remote(e.data.data)}}}catch(e){}window.addEventListener("storage",e=>{if(e.key===SK&&e.newValue)try{remote(JSON.parse(e.newValue))}catch(err){}})}
function installManifest(){
try{let m={name:"Ritmo · Diario de entrenamiento",short_name:"Ritmo",start_url:location.href,display:"standalone",background_color:"#f4f6fc",theme_color:state.settings.accent||"#3949ab",description:"Tu rutina y progreso, siempre contigo.",icons:[{src:"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 192 192'%3E%3Crect width='192' height='192' rx='48' fill='%233949ab'/%3E%3Ctext x='96' y='132' text-anchor='middle' font-size='118' fill='white'%3E%E2%9C%A6%3C/text%3E%3C/svg%3E",sizes:"192x192",type:"image/svg+xml"}]};document.getElementById("manifestLink").href="data:application/manifest+json,"+encodeURIComponent(JSON.stringify(m))}catch(e){}
}
async function init(){
let loaded=await Store.load();state=cp(loaded.data);
if(loaded.warning){toast(loaded.warning,{label:"Exportar",run:exportData});let recovery=await Store.save(state);state=cp(Store.current);setStatus(recovery.idbOK,recovery.idbOK?"Recuperado ✓":recovery.ok?"Copia local":"Error al guardar")}
if(loaded.first){let r=await Store.save(state);state=cp(Store.current);setStatus(r.idbOK,r.idbOK?"Guardado ✓":r.ok?"Guardado local":"Error al guardar");if(!r.ok)toast("No hay almacenamiento disponible. Exporta una copia ahora.",{label:"Exportar",run:exportData})}
persistText=await persistPermission();applySettings();setupSync();render();
if(!Store.mode.idb&&!loaded.first){setStatus(false,Store.mode.local?"Solo copia local ⚠":"Error al guardar");if(!Store.mode.local)toast("El almacenamiento del navegador no está disponible. Exporta tus datos.",{label:"Exportar",run:exportData})}
if(state.settings.lastBackup&&Date.now()-state.settings.lastBackup>14*86400000)setTimeout(()=>toast("Han pasado dos semanas desde tu última copia. Exporta un JSON desde Ajustes."),1800);
}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"&&state)saveSoon()});
window.addEventListener("pagehide",()=>{if(state){try{localStorage.setItem(SK,JSON.stringify(state));localStorage.setItem(BK,JSON.stringify(Store.backups))}catch(e){}saveSoon()}});
window.addEventListener("beforeunload",()=>{if(state){try{localStorage.setItem(SK,JSON.stringify(state))}catch(e){}saveSoon()}});
window.addEventListener("dblclick",e=>e.preventDefault(),{passive:false});let touchAt=0;document.addEventListener("touchend",e=>{let n=Date.now();if(n-touchAt<300)e.preventDefault();touchAt=n},{passive:false});document.addEventListener("gesturestart",e=>e.preventDefault(),{passive:false});document.addEventListener("gesturechange",e=>e.preventDefault(),{passive:false});document.addEventListener("gestureend",e=>e.preventDefault(),{passive:false});
try{matchMedia("(prefers-color-scheme: dark)").addEventListener("change",()=>{if(state&&state.settings.theme==="auto")applySettings()})}catch(e){}
init().catch(e=>{state=defaults();setStatus(false,"Error de inicio");render();toast("No pude leer el almacenamiento. Exporta los datos visibles.",{label:"Exportar",run:exportData})});
